export function targetGap(fact,target,baseYear,goalYear){
 if(![fact,target,baseYear,goalYear].every(Number.isFinite)||goalYear<=baseYear) return null;
 const years=goalYear-baseYear,gap=target-fact;
 return {years,gap,annualChange:gap/years,annualRelativePercent:fact>0&&target>0?100*((target/fact)**(1/years)-1):null};
}
export function targetScenario(fact,annualChange,baseYear,goalYear){
 if(![fact,annualChange,baseYear,goalYear].every(Number.isFinite)||!Number.isInteger(baseYear)||!Number.isInteger(goalYear)||goalYear<baseYear||goalYear-baseYear>50)return [];
 return Array.from({length:goalYear-baseYear+1},(_,i)=>({year:baseYear+i,value:fact+annualChange*i}));
}
