function domainsPage(ctx){
 const root=start(ctx),data=ctx.youth.documentary?.text||{},frames=arr(data.frames),rows=arr(data.domainEvidence),id=rows.some(r=>r.domain_id===ctx.state.frame)?ctx.state.frame:'education_youth',selected=rows.find(r=>r.domain_id===id)||rows[0],nodes=arr(ctx.youth.documentary?.network?.nodes),docMap=new Map(arr(data.documents).map(d=>[d.document_id,d]));
 append(root,toolbar(select('Содержательная область',rows.map(r=>[r.domain_id,r.domain_name]),selected?.domain_id,v=>ctx.set({frame:v}))),note('Это матрица документальных свидетельств. Число упоминаний и наличие словарного маркера не превращаются в сводный балл эффективности. Отсутствие маркера требует чтения документа.'));
 if(selected){let ids=[];try{ids=JSON.parse(selected.evidence_node_ids_json||'[]');}catch{}const evidence=nodes.filter(n=>ids.includes(n.node_id));append(root,stats([['Цели с маркером',fmt(num(selected.goal_nodes),0),'документальные карточки'],['Задачи с маркером',fmt(num(selected.task_nodes),0),'документальные карточки'],['Результаты с маркером',fmt(num(selected.result_nodes),0),'не сведения об исполнении'],['Связанные статистические коды',fmt(num(selected.approved_statistical_codes),0),'проверенные соответствия']]),panel(selected.domain_name,'Карточки документа, на которых основана матрица.',table(evidence.map(n=>({kind:kindLabel(n.kind),title:n.title,document:documentName(docMap.get(n.document_id)),url:n.source_url,locator:n.source_xpath||n.source_card_id,id:n.node_id})),[{key:'kind',label:'Тип'},{key:'title',label:'Свидетельство'},{key:'document',label:'Документ'},{key:'url',label:'Источник',render:url=>a('Открыть',url)},{key:'locator',label:'Указатель'}],{filename:'youth-domain-evidence.csv',pageSize:10,onSelect:r=>ctx.go('network',{layer:'documentary',node:r.id})})));
 }
 append(root,panel('Обзор 18 областей','Показатели пересекаются между областями; их нельзя складывать в сумму уникальных мер.',table(rows.map(r=>({...r,goals:num(r.goal_nodes),tasks:num(r.task_nodes),results:num(r.result_nodes),indicators:num(r.indicator_nodes),codes:num(r.approved_statistical_codes)})),[{key:'domain_name',label:'Область'},{key:'goals',label:'Цели',numeric:true,decimals:0},{key:'tasks',label:'Задачи',numeric:true,decimals:0},{key:'results',label:'Результаты',numeric:true,decimals:0},{key:'indicators',label:'Показатели',numeric:true,decimals:0},{key:'codes',label:'Статистические коды',numeric:true,decimals:0}],{filename:'youth-domains.csv',pageSize:18,onSelect:r=>ctx.set({frame:r.domain_id})})));
 return end(ctx,root);
}

